const test = require('node:test');
const assert = require('node:assert/strict');
const {rotate} = require('../carousel.cjs');
test('signed wrapping and immutability', () => {
  for (const [steps, expected] of [[1,[4,1,2,3]],[-1,[2,3,4,1]],[9,[4,1,2,3]],[-9,[2,3,4,1]],[0,[1,2,3,4]],[4,[1,2,3,4]]]) {
    const input=[1,2,3,4];
    const out=rotate(input,steps);
    assert.deepEqual(out,expected);
    assert.deepEqual(input,[1,2,3,4]);
    assert.notEqual(out,input);
  }
  const empty=[];
  assert.deepEqual(rotate(empty,12),[]);
  assert.notEqual(rotate(empty,0),empty);
  const object={};
  assert.equal(rotate([object],1)[0],object);
});

